function parse_link_lines(string $raw,string $field): array {$links=[];$lines=preg_split('/\R/u',$raw);if($lines===false)throw new RuntimeException($field.' could not be read.');foreach($lines as $line){$line=trim($line);if($line==='')continue;$separator=strpos($line,'|');if($separator===false)throw new RuntimeException('Each '.$field.' entry must use the format Label | URL.');$label=trim(substr($line,0,$separator));$href=trim(substr($line,$separator+1));if($label===''||$href==='')throw new RuntimeException('Each '.$field.' entry needs both a label and a URL.');$links[]=['label'=>$label,'href'=>$href];}return $links;}
function parse_social_links(string $raw): array {return parse_link_lines($raw,'social link');}
function parse_bilingual_link_lines(string $english,string $arabic,string $field): array {$englishLines=preg_split('/\R/u',$english);$arabicLines=preg_split('/\R/u',$arabic);if($englishLines===false||$arabicLines===false)throw new RuntimeException($field.' could not be read.');$en=[];$ar=[];foreach($englishLines as $index=>$line){$line=trim($line);if($line==='')continue;$separator=strpos($line,'|');if($separator===false)throw new RuntimeException('Each English '.$field.' entry must use the format Label | URL.');$label=trim(substr($line,0,$separator));$href=trim(substr($line,$separator+1));if($label===''||$href==='')throw new RuntimeException('Each English '.$field.' entry needs both a label and a URL.');$en[]=['label'=>$label,'href'=>$href];$translated=trim((string)($arabicLines[$index]??''));$ar[]=$translated===''?[]:['label'=>$translated];}return ['en'=>$en,'ar'=>$ar];}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{require_csrf();$action=(string)($_POST['action']??'');
  if($action==='login'){$q=db()->prepare('SELECT id,password_hash,is_active FROM cms_users WHERE email=:email');$q->execute(['email'=>strtolower(trim((string)($_POST['email']??'')))]);$row=$q->fetch();if(!$row||!(int)$row['is_active']||!password_verify((string)($_POST['password']??''),$row['password_hash']))throw new RuntimeException('Email or password is incorrect.');session_regenerate_id(true);$_SESSION['user_id']=(int)$row['id'];redirect('./');}
  if($action==='change-password'){if(!$user)throw new RuntimeException('Sign in to continue.');$q=db()->prepare('SELECT password_hash FROM cms_users WHERE id=:id');$q->execute(['id'=>(int)$user['id']]);$hash=$q->fetchColumn();$new=(string)($_POST['new_password']??'');if(!password_verify((string)($_POST['current_password']??''),(string)$hash)||strlen($new)<12)throw new RuntimeException('Check your current password and enter a new password of at least 12 characters.');$q=db()->prepare('UPDATE cms_users SET password_hash=:hash WHERE id=:id');$q->execute(['hash'=>password_hash($new,PASSWORD_DEFAULT),'id'=>(int)$user['id']]);session_regenerate_id(true);flash('Your password was changed.');redirect('./?page=account');}
  if($action==='logout'){unset($_SESSION['user_id']);session_regenerate_id(true);redirect('./?page=login');}
  if(!$user)throw new RuntimeException('Sign in to continue.');
  if($action==='upload-media-picker'){header('Content-Type: application/json; charset=utf-8');try{$id=MediaService::upload($_FILES['image']??[],(int)$user['id']);$q=db()->prepare('SELECT id,filename,original_name,mime_type,alt_text,is_active FROM cms_media WHERE id=:id');$q->execute(['id'=>$id]);echo json_encode(['asset'=>$q->fetch()],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $uploadError){http_response_code(400);echo json_encode(['error'=>$uploadError->getMessage()],JSON_UNESCAPED_UNICODE);}exit;}
  if($action==='save-sections'){$payload=json_decode_array((string)($_POST['payload']??''));ContentValidator::sections($payload);save_draft('sections',$payload,(int)$user['id']);flash('Draft saved. Preview it before publishing.');redirect('./?page=sections');}
  if($action==='save-settings'){$existingDoc=content_doc('site',true);$existingSettings=$existingDoc['settings']??[];$settings=['brand'=>trim((string)($_POST['brand']??'')),'logo_media_id'=>(($_POST['logo_media_id']??'')===''?null:(int)$_POST['logo_media_id']),'favicon_media_id'=>(($_POST['favicon_media_id']??'')===''?null:(int)$_POST['favicon_media_id']),'tagline'=>trim((string)($_POST['tagline']??'')),'email'=>trim((string)($_POST['email']??'')),'phone'=>trim((string)($_POST['phone']??'')),'location'=>trim((string)($_POST['location']??'')),'footer'=>trim((string)($_POST['footer']??''))];$translations=is_array($existingSettings['translations']??null)?$existingSettings['translations']:[];$ar=is_array($translations['ar']??null)?$translations['ar']:[];foreach(['brand','tagline','email','phone','location','footer'] as $field)if(array_key_exists($field.'_ar',$_POST))$ar[$field]=trim((string)$_POST[$field.'_ar']);if(array_key_exists('navigation_text',$_POST)){$links=parse_bilingual_link_lines((string)$_POST['navigation_text'],(string)($_POST['navigation_ar_text']??''),'navigation links');$settings['navigation']=$links['en'];if(array_key_exists('navigation_ar_text',$_POST))$ar['navigation']=$links['ar'];}else $settings['navigation']=json_decode_array((string)($_POST['navigation']??'[]'));if(array_key_exists('social_links_ar_text',$_POST)){$links=parse_bilingual_link_lines((string)($_POST['social_links_text']??''),(string)$_POST['social_links_ar_text'],'social links');$settings['social_links']=$links['en'];$ar['social_links']=$links['ar'];}else $settings['social_links']=parse_social_links((string)($_POST['social_links_text']??''));if($translations!==[]||array_key_exists('brand_ar',$_POST)||array_key_exists('navigation_ar_text',$_POST)||array_key_exists('social_links_ar_text',$_POST)){$translations['ar']=$ar;$settings['translations']=$translations;}$payload=['settings'=>$settings];ContentValidator::settings($payload);save_draft('site',$payload,(int)$user['id']);flash('Website settings saved as a draft.');redirect('./?page=settings');}if($action==='save-design'){$fields=['primary','secondary','accent','background','surface','text','muted','font','heading_font','base_size','radius','spacing'];$d=[];foreach($fields as $f)$d[$f]=trim((string)($_POST[$f]??''));$payload=['design'=>$d];ContentValidator::design($payload);save_draft('design',$payload,(int)$user['id']);flash('Design settings saved as a draft.');redirect('./?page=design');}
  if($action==='publish'){$key=(string)($_POST['document']??'');if(!in_array($key,['sections','site','design'],true))throw new RuntimeException('Invalid document.');publish_draft($key,(int)$user['id']);flash('Changes published to the website.');$target=match($key){'site'=>'settings',default=>$key};redirect('./?page='.$target);}
  if($action==='upload-media'){$id=MediaService::upload($_FILES['image']??[],(int)$user['id']);flash('Image uploaded and added to the media library.');redirect('./?page=media');}
  if($action==='save-alt'){$id=(int)($_POST['media_id']??0);$q=db()->prepare('UPDATE cms_media SET alt_text=:alt WHERE id=:id');$q->execute(['alt'=>mb_substr(trim((string)($_POST['alt_text']??'')),0,500),'id'=>$id]);flash('Alternative text saved.');redirect('./?page=media');}
  if($action==='archive-media'){$id=(int)($_POST['media_id']??0);if(media_in_use($id))throw new RuntimeException('This image is in use by published or draft content. Replace or remove it from that content before archiving.');$q=db()->prepare('UPDATE cms_media SET is_active=0 WHERE id=:id');$q->execute(['id'=>$id]);flash('Image archived. The file is retained on disk.');redirect('./?page=media');}
  if($action==='add-user'){if($user['role']!=='admin')throw new RuntimeException('Administrator access is required.');$name=trim((string)($_POST['name']??''));$email=filter_var((string)($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pw=(string)($_POST['password']??'');if(!$email||mb_strlen($name)<2||strlen($pw)<12)throw new RuntimeException('Enter a valid name, email, and a password of at least 12 characters.');$q=db()->prepare('INSERT INTO cms_users(name,email,password_hash,role) VALUES(:name,:email,:hash,:role)');$q->execute(['name'=>$name,'email'=>$email,'hash'=>password_hash($pw,PASSWORD_DEFAULT),'role'=>($_POST['role']??'editor')==='admin'?'admin':'editor']);flash('User created.');redirect('./?page=users');}
  if($action==='toggle-user'){if($user['role']!=='admin')throw new RuntimeException('Administrator access is required.');$id=(int)($_POST['user_id']??0);if($id===(int)$user['id'])throw new RuntimeException('You cannot disable your own account.');$q=db()->prepare('UPDATE cms_users SET is_active=IF(is_active=1,0,1) WHERE id=:id');$q->execute(['id'=>$id]);flash('User access updated.');redirect('./?page=users');}
  if($action==='restore-revision'){$id=(int)($_POST['revision_id']??0);$q=db()->prepare('SELECT document_key,payload_json FROM cms_revisions WHERE id=:id');$q->execute(['id'=>$id]);$revision=$q->fetch();if(!$revision)throw new RuntimeException('Revision was not found.');$payload=json_decode_array($revision['payload_json']);$ids=[];$scan=function($v)use(&$scan,&$ids){if(!is_array($v))return;foreach($v as $k=>$x){if(in_array($k,['image_id','logo_media_id','favicon_media_id'],true)&&is_int($x))$ids[]=$x;elseif(is_array($x))$scan($x);}};$scan($payload);foreach(array_unique($ids) as $mediaId){$q=db()->prepare('UPDATE cms_media SET is_active=1 WHERE id=:id');$q->execute(['id'=>$mediaId]);}save_draft((string)$revision['document_key'],$payload,(int)$user['id']);flash('Revision restored as a draft. Review and publish it when ready.');$target=match((string)$revision['document_key']){'sections'=>'sections','site'=>'settings','design'=>'design',default=>'revisions'};redirect('./?page='.$target);}
  if($action==='create-backup'){if($user['role']!=='admin')throw new RuntimeException('Administrator access is required.');$name=BackupService::create();flash('Backup created: '.$name);redirect('./?page=backups');}
  if($action==='restore-backup'){if($user['role']!=='admin')throw new RuntimeException('Administrator access is required.');BackupService::restore($_FILES['backup']??[]);unset($_SESSION['user_id']);flash('Backup restored. Sign in again.');redirect('./?page=login');}
  throw new RuntimeException('Unknown action.');
 }catch(Throwable $e){$error=$e->getMessage();}
