<?php elseif($page==='users'&&$user['role']==='admin'):?><section class="card"><h2>Users</h2><?php foreach(db()->query('SELECT id,name,email,role,is_active FROM cms_users ORDER BY id') as $account):?><div class="row"><p><?=e($account['name'])?> · <?=e($account['email'])?> · <?=e($account['role'])?> · <?=((int)$account['is_active']?'Active':'Disabled')?></p><?php if((int)$account['id']!==(int)$user['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle-user"><input type="hidden" name="user_id" value="<?=(int)$account['id']?>"><button class="button secondary"><?=((int)$account['is_active']?'Disable':'Enable')?></button></form><?php endif;?></div><?php endforeach;?></section><form class="card form" method="post"><h2>Add administrator or editor</h2><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add-user"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Initial password<input name="password" type="password" minlength="12" required></label><label>Role<select name="role"><option>editor</option><option>admin</option></select></label><button class="button">Create account</button></form>
<?php elseif($page==='account'):?><form class="card form" method="post"><h2>Change password</h2><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="change-password"><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><label>New password (12 characters minimum)<input name="new_password" type="password" minlength="12" autocomplete="new-password" required></label><button class="button">Change password</button></form><?php elseif($page==='revisions'):?><section class="card"><h2>Revision history</h2><?php foreach(db()->query('SELECT id,document_key,revision,state,created_at FROM cms_revisions ORDER BY id DESC LIMIT 100') as $r):?><div class="row revision-row"><p><?=e($r['document_key'])?> · #<?=(int)$r['revision']?> · <?=e($r['state'])?> · <?=e($r['created_at'])?></p><form method="post" onsubmit="return confirm('Restore as a draft?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="restore-revision"><input type="hidden" name="revision_id" value="<?=(int)$r['id']?>"><button class="button secondary">Restore as draft</button></form></div><?php endforeach;?></section><?php elseif($page==='backups'&&$user['role']==='admin'):?><section class="card"><h2>Backup &amp; restore</h2><p>Backups are stored in the protected smayo_private storage folder and include database rows and uploaded media.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create-backup"><button class="button">Create backup</button></form><form method="post" enctype="multipart/form-data" class="upload-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="restore-backup"><label>Restore archive<input type="file" name="backup" accept=".zip,application/zip" required></label><button class="button secondary" onclick="return confirm('A safety backup will be created before restoring.')">Restore backup</button></form><?php foreach(glob(SMAYO_ROOT.'/storage/backups/smayo-*.zip')?:[] as $backup):$backupName=basename($backup);?><p><a href="?page=backups&amp;download=<?=e(rawurlencode($backupName))?>">Download <?=e($backupName)?></a></p><?php endforeach;?></section>
<?php else:?><section class="card"><h2>Unavailable</h2></section><?php endif;?></div></main><?php endif;?></body></html>
